-- Treejoin.hs - nofib spectral/treejoin, verbatim port to the NanoPrelude
-- dialect. nofib FAST opts: runtime_files/1500.1 and 1500.2, embedded
-- byte-exact below as generated chunk literals (the readInt parsing of the
-- raw bytes is part of the workload and is kept). The replicateM_ 100
-- wrapper repeats identical work and is dropped; the forceTree consumption
-- becomes a structural hash of the joined tree.
module Treejoin where
import Prelude()
import NanoPrelude

append :: [a] -> [a] -> [a]
append []     ys = ys
append (x:xs) ys = x : append xs ys

dropWhileL :: (a -> Bool) -> [a] -> [a]
dropWhileL p [] = []
dropWhileL p l@(x:xs) = if p x then dropWhileL p xs else l

err :: a
err = err

data Tree e = Node Int (Tree e) (Tree e) | Leaf Int e | Empty

type Entity = (Int,Int,Int)
type Join = (Int,Int,Int,Int,Int)

insertT :: Int -> e -> Tree e -> Tree e
insertT k e (Node k' l r) = if k <= k' then Node k' (insertT k e l) r
                            else Node k' l (insertT k e r)
insertT k e l0@(Leaf k' _) =
  if k < k' then Node k l' l0
  else if k > k' then Node k' l0 l'
  else err
    where l' = Leaf k e
insertT k e Empty = Leaf k e

lookupT :: Int -> Tree e -> Maybe e
lookupT k (Node k' l r) = if k <= k' then lookupT k l else lookupT k r
lookupT k (Leaf k' e) = if k == k' then Just e else Nothing
lookupT k Empty = Nothing

isDigitC, isSpaceC :: Int -> Bool
isDigitC c = 48 <= c && c <= 57
isSpaceC c = c == 32 || c == 10 || c == 9 || c == 13

readTree :: (Entity -> Int) -> [Int] -> Tree Entity -> Tree Entity
readTree fk [] t = t
readTree fk s t =
    let (f,s') = readInt s
        (g,s'') = readInt s'
        (h,s''') = readInt s''
        e = (f,g,h)
        k = fk e
    in
        readTree fk s''' (insertT k e t)

readInt :: [Int] -> (Int,[Int])
readInt s0 = readInt' 0 s0 where
        readInt' n s@(c:cs) = if isDigitC c then readInt' (n*10 + c - 48) cs
                              else fin n s
        readInt' n s = fin n s
        fin n s = let s' = dropWhileL isSpaceC s in (n,s')

join :: Tree Entity -> Tree Entity -> Tree Join -> Tree Join
join Empty _ j = j
join _ Empty j = j
join (Leaf k (a,b,c)) t j = case lookupT c t of
                         Nothing -> j
                         Just (d,e,f) -> insertT c (a,b,c,d,e) j
join (Node k l r) t j = join l t (join r t j)

-- forceTree boundary: structural hash of the joined tree
hashT :: Int -> Tree Join -> Int
hashT acc Empty = acc*31 + 7
hashT acc (Leaf k (a,b,c,d,e)) = ((((((acc*31 + k)*31 + a)*31 + b)*31 + c)*31 + d)*31 + e)
hashT acc (Node k l r) = hashT (hashT (acc*31 + k) l) r

bench :: Int
-- SIM SCALE (user ruling 2026-07-30): the nofib FAST input needs 1e8+
-- operations, which this RTL simulation (~1e4 cycles/s) cannot reach.
-- fast* is the upstream FAST value, sim* is what is actually run; both
-- backends compile the same one. See benchmarks/porting_nofib.md.
fastRecs, simRecs :: Int
fastRecs = 1500  -- records per file
simRecs = 300

bench = hashT 0 (join a0 b0 Empty)
  where
    a0 = readTree (\(x,_,_) -> x) (takeB simRecs inputA) Empty
    b0 = readTree (\(x,_,_) -> x) (takeB simRecs inputB) Empty

-- the raw bytes of the first n records: one record per line upstream
takeB :: Int -> [Int] -> [Int]
takeB n [] = []
takeB n (c:cs) = if c == 10
                 then (if n <= 1 then [10] else c : takeB (n-1) cs)
                 else c : takeB n cs


  where
    a0 = readTree (\(x,_,_) -> x) inputA Empty
    b0 = readTree (\(x,_,_) -> x) inputB Empty

main :: Int
main = bench

